interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;

type Status = (typeof STATUSES)[number];

const EVENT_ORDER = "order";
const EVENT_CANCEL = "cancel";
const EVENT_SHIP = "ship";
const EVENT_RESTOCK = "restock";
const EVENT_EXPIRE = "expire";

function getOnHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

/**
 * Re-scan the backorder queue and fulfill as many pending wants as current
 * stock allows. Backordered orders are served in arrival order (FIFO).
 */
function backfillQueue(
  stock: Record<string, number>,
  queue: string[],
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const want = pendingWants[queue[position]];
    const onHand = getOnHand(stock, want.item);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[queue[position]] = { item: want.item, qty: want.qty };
      orders[queue[position]] = "reserved";
      delete pendingWants[queue[position]];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function statusCounts(orders: Record<string, string>): Record<Status, number> {
  const counts = {} as Record<Status, number>;
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id] as Status] = counts[orders[id] as Status] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function isValidId(id: unknown): id is string {
  return typeof id === "string" && id.length > 0;
}

function isValidItem(item: unknown): item is string {
  return typeof item === "string" && item.length > 0;
}

function isValidQty(qty: unknown): qty is number {
  return Number.isInteger(qty) && (qty as number) >= 1;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const fail = (index: number, reason: string): FulfillmentResult => {
    return { ok: false, error: "event " + index + ": " + reason };
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return fail(index, "malformed");
    }

    if (event.type === EVENT_ORDER) {
      if (!isValidId(event.id)) {
        return fail(index, "bad id");
      }
      if (orders[event.id] !== undefined) {
        return fail(index, "duplicate order");
      }
      if (!isValidItem(event.item)) {
        return fail(index, "bad item");
      }
      if (!isValidQty(event.qty)) {
        return fail(index, "bad qty");
      }
      const available = getOnHand(stock, event.item);
      if (available >= event.qty) {
        stock[event.item] = available - event.qty;
        reserved[event.id] = { item: event.item, qty: event.qty };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty };
        orders[event.id] = "backordered";
      }
    } else if (event.type === EVENT_CANCEL) {
      if (!isValidId(event.id)) {
        return fail(index, "bad id");
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = getOnHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        backfillQueue(stock, queue, reserved, pendingWants, orders);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === EVENT_SHIP) {
      if (!isValidId(event.id)) {
        return fail(index, "bad id");
      }
      if (event.qty !== undefined && !isValidQty(event.qty)) {
        return fail(index, "bad qty");
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || event.qty === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if (event.qty < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - event.qty;
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === EVENT_RESTOCK) {
      if (!isValidItem(event.item)) {
        return fail(index, "bad item");
      }
      if (!isValidQty(event.qty)) {
        return fail(index, "bad qty");
      }
      stock[event.item] = getOnHand(stock, event.item) + event.qty;
      backfillQueue(stock, queue, reserved, pendingWants, orders);
    } else if (event.type === EVENT_EXPIRE) {
      if (!isValidId(event.id)) {
        return fail(index, "bad id");
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        stock[holding.item] = getOnHand(stock, holding.item) + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        backfillQueue(stock, queue, reserved, pendingWants, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return fail(index, "bad type");
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

